{"implementation":"def solve(case):
    from fractions import Fraction
    import math

    def require_int(value, field):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(field + " must be an integer")
        return value

    def require_importance(value, field):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(field + " must be a finite nonnegative number")
        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError(field + " must be a finite nonnegative number")
        if value < 0:
            raise ValueError(field + " must be a finite nonnegative number")
        return Fraction(str(value))

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case:
        raise ValueError("missing required field: segments")
    if "budget" not in case:
        raise ValueError("missing required field: budget")

    segments = case["segments"]
    budget = require_int(case["budget"], "budget")
    if not isinstance(segments, list) or not segments:
        raise ValueError("segments must be a nonempty list")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    names = []
    importances = []
    minimums = []
    capacities = []
    seen_names = set()

    for index, segment in enumerate(segments):
        prefix = "segments[" + str(index) + "]"
        if not isinstance(segment, dict):
            raise ValueError(prefix + " must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing required field: " + prefix + "." + field)

        name = segment["name"]
        if not isinstance(name, str) or not name:
            raise ValueError(prefix + ".name must be a nonempty string")
        if name in seen_names:
            raise ValueError("segment names must be unique")
        seen_names.add(name)

        importance = require_importance(segment["importance"], prefix + ".importance")
        minimum = require_int(segment["minimum"], prefix + ".minimum")
        capacity = require_int(segment["capacity"], prefix + ".capacity")
        if minimum < 0:
            raise ValueError(prefix + ".minimum must be nonnegative")
        if capacity < minimum:
            raise ValueError(prefix + ".capacity must be at least its minimum")

        names.append(name)
        importances.append(importance)
        minimums.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(minimums)
    capacity_total = sum(capacities)
    if budget < minimum_total:
        raise ValueError("budget is below the minimum quota sum")
    if budget > capacity_total:
        raise ValueError("budget exceeds total capacity")

    allocations = list(minimums)
    remaining = budget - minimum_total
    while remaining:
        best_index = None
        best_priority = None
        for index in range(len(segments)):
            if allocations[index] >= capacities[index]:
                continue
            priority = importances[index] / (allocations[index] + 1)
            if best_index is None or priority > best_priority:
                best_index = index
                best_priority = priority
        allocations[best_index] += 1
        remaining -= 1

    return {
        "allocations": allocations,
        "name_mapping": {names[index]: allocations[index] for index in range(len(names))},
        "total": sum(allocations),
    }
"}
